-- FEELINGS Web completion migration. Review against the remote schema before applying.
create extension if not exists pgcrypto;
alter table if exists public.couples add column if not exists relationship_date date;
alter table if exists public.couples add column if not exists invite_code text;
alter table if exists public.couples add column if not exists invite_expires_at timestamptz;
create table if not exists public.care_signals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, couple_id uuid not null references public.couples(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, receiver_id uuid not null references auth.users(id) on delete cascade, signal text not null, emoji text, text text, read_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.memories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, couple_id uuid not null references public.couples(id) on delete cascade, title text not null, description text, date date, photo_path text, location text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.important_dates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, couple_id uuid not null references public.couples(id) on delete cascade, title text not null, date date not null, emoji text, repeat_yearly boolean not null default false, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.calendar_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, couple_id uuid not null references public.couples(id) on delete cascade, title text not null, date date not null, time time, reminder_minutes integer not null default 0, description text, recurrence text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.diary_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, couple_id uuid not null references public.couples(id) on delete cascade, title text, body text not null, date date not null default current_date, photo_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, text text, type text, target_id uuid, created_at timestamptz not null default now(), read_at timestamptz);
create table if not exists public.notification_preferences (user_id uuid primary key references auth.users(id) on delete cascade, moods boolean not null default true, reactions boolean not null default true, care boolean not null default true, dates boolean not null default true, memories boolean not null default true, diary boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.privacy_settings (user_id uuid primary key references auth.users(id) on delete cascade, mood_visibility text not null default 'private', cycle_visibility text not null default 'private', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.invitations (id uuid primary key default gen_random_uuid(), couple_id uuid not null references public.couples(id) on delete cascade, creator_id uuid not null references auth.users(id) on delete cascade, code_hash text not null, expires_at timestamptz not null, consumed_at timestamptz, created_at timestamptz not null default now());
create index if not exists care_signals_couple_created_idx on public.care_signals(couple_id, created_at desc);
create index if not exists memories_couple_created_idx on public.memories(couple_id, created_at desc);
create index if not exists important_dates_couple_date_idx on public.important_dates(couple_id, date);
create index if not exists calendar_events_couple_date_idx on public.calendar_events(couple_id, date);
create index if not exists diary_entries_couple_created_idx on public.diary_entries(couple_id, created_at desc);
create index if not exists notifications_user_read_created_idx on public.notifications(user_id, read_at, created_at desc);
create or replace function public.get_my_couple() returns jsonb language plpgsql security invoker set search_path=public as $$ declare c_id uuid; c_created timestamptz; c_rel date; p_id uuid; p_name text; p_avatar text; begin select cm.couple_id into c_id from public.couple_members cm where cm.user_id=auth.uid() limit 1; if c_id is null then return null; end if; select c.created_at,c.relationship_date into c_created,c_rel from public.couples c where c.id=c_id; select cm.user_id into p_id from public.couple_members cm where cm.couple_id=c_id and cm.user_id<>auth.uid() limit 1; if p_id is not null then select name,avatar_path into p_name,p_avatar from public.profiles where id=p_id; end if; return jsonb_build_object('id',c_id,'created_at',c_created,'relationship_date',c_rel,'partner',case when p_id is null then null else jsonb_build_object('id',p_id,'name',p_name,'avatar_path',p_avatar) end); end $$;
revoke all on function public.get_my_couple() from public; grant execute on function public.get_my_couple() to authenticated;
do $$ begin if to_regclass('public.care_signals') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='care_signals') then alter publication supabase_realtime add table public.care_signals; end if; if to_regclass('public.memories') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='memories') then alter publication supabase_realtime add table public.memories; end if; if to_regclass('public.important_dates') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='important_dates') then alter publication supabase_realtime add table public.important_dates; end if; if to_regclass('public.calendar_events') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='calendar_events') then alter publication supabase_realtime add table public.calendar_events; end if; if to_regclass('public.diary_entries') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='diary_entries') then alter publication supabase_realtime add table public.diary_entries; end if; if to_regclass('public.notifications') is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications') then alter publication supabase_realtime add table public.notifications; end if; exception when undefined_object then null; end $$;

-- RLS for the Web-only additive tables. Existing policies are preserved; names are checked before creation.
do $$
declare t text; pol text;
begin
  foreach t in array array['care_signals','memories','important_dates','calendar_events','diary_entries','notifications','notification_preferences','privacy_settings','invitations'] loop
    execute format('alter table public.%I enable row level security',t);
  end loop;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='care_signals' and policyname='care_select_members') then create policy care_select_members on public.care_signals for select using (auth.uid()=sender_id or auth.uid()=receiver_id); end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='care_signals' and policyname='care_insert_sender') then create policy care_insert_sender on public.care_signals for insert with check (auth.uid()=sender_id and auth.uid()=user_id and couple_id=public.active_couple_id()); end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='care_signals' and policyname='care_ack_receiver') then create policy care_ack_receiver on public.care_signals for update using (auth.uid()=receiver_id) with check (auth.uid()=receiver_id); end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='care_signals' and policyname='care_delete_sender') then create policy care_delete_sender on public.care_signals for delete using (auth.uid()=sender_id); end if;
  foreach t in array array['memories','important_dates','calendar_events','diary_entries'] loop
    pol:=t||'_member_select'; if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=pol) then execute format('create policy %I on public.%I for select using (couple_id=public.active_couple_id())',pol,t); end if;
    pol:=t||'_owner_insert'; if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=pol) then execute format('create policy %I on public.%I for insert with check (user_id=auth.uid() and couple_id=public.active_couple_id())',pol,t); end if;
    pol:=t||'_owner_update'; if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=pol) then execute format('create policy %I on public.%I for update using (user_id=auth.uid() and couple_id=public.active_couple_id()) with check (user_id=auth.uid() and couple_id=public.active_couple_id())',pol,t); end if;
    pol:=t||'_owner_delete'; if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=pol) then execute format('create policy %I on public.%I for delete using (user_id=auth.uid() and couple_id=public.active_couple_id())',pol,t); end if;
  end loop;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='notifications' and policyname='notifications_owner_select') then create policy notifications_owner_select on public.notifications for select using (user_id=auth.uid()); end if;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='notifications' and policyname='notifications_owner_update') then create policy notifications_owner_update on public.notifications for update using (user_id=auth.uid()) with check (user_id=auth.uid()); end if;
  foreach t in array array['notification_preferences','privacy_settings'] loop
    pol:=t||'_owner'; if not exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=pol) then execute format('create policy %I on public.%I for all using (user_id=auth.uid()) with check (user_id=auth.uid())',pol,t); end if;
  end loop;
  if not exists(select 1 from pg_policies where schemaname='public' and tablename='invitations' and policyname='invitations_none') then create policy invitations_none on public.invitations for all using (false) with check (false); end if;
end $$;
